let mensagemFinal = items
  .map(item => item.json.mensagem)
  .join("\n\n");

return [
  {
    json: {
      output: mensagemFinal
    }
  }
];

return items.map(item => {
  const nome = item.json.nome;
  const numero = item.json.numero;
  const jogo = item.json.jogos;

  return {
    json: {
      nome: nome,
      numero: numero,
      cotas: jogo.quantidade_cotas,
      valor: jogo.subtotal,
      link_tabela: jogo.link_tabela, // necessário para o node acessar a planilha
      "nome_do_jogo": jogo.nome_jogo,
      nomefolha:"Página1"
    }
  };
});

const inputArray = items.map(i => i.json);

const mapa = {};

// percorre cada objeto do array
for (const obj of inputArray) {
  const nome = obj.nome;

  if (!mapa[nome]) {
    // cria novo objeto
    mapa[nome] = { ...obj };
  } else {
    // soma apenas cotas e valor
    mapa[nome].cotas += obj.cotas || 0;
    mapa[nome].valor += obj.valor || 0;

    // adiciona os outros campos que ainda não existem
    for (const key of Object.keys(obj)) {
      if (!(key in mapa[nome])) {
        mapa[nome][key] = obj[key];
      }
    }
  }
}

// transforma de volta em array para n8n
return Object.values(mapa).map(obj => ({ json: obj }));

// pega o primeiro (e único) objeto do array de entrada
const data = items[0].json;

// monta a mensagem
const mensagem = `
✅ TABELA ATUALIZADA COM SUCESSO

Jogo: ${data.nome_do_jogo || 'N/A'}

Nome: ${data.nome}
Número: ${data.numero}

Cotas adicionadas nesta operação: ${data.cotas}
Valor adicionado nesta operação: R$ ${data.valor}

Link da tabela:
${data.link_tabela || 'N/A'}
`;

// retorna no formato do n8n
return [
  {
    json: {
      mensagem
    }
  }
];

// pega o primeiro item do input
const data = items[0].json;

// monta a mensagem de erro
const mensagem = `
❌ ERRO AO ATUALIZAR TABELA

Jogo: ${data.nome_do_jogo || 'N/A'}

Nome: ${data.nome}
Número: ${data.numero}

Cotas que não foram adicionadas nesta operação: ${data.cotas}
Valor que não foi adicionado nesta operação: R$ ${data.valor}

Link da tabela:
${data.link_tabela || 'N/A'}
`;

// retorna no formato do n8n
return [
  {
    json: {
      mensagem
    }
  }
];

